<?php require '../includes/bootstrap.php';need_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';$response=trim($_POST['response']??'');if($id&&in_array($status,['pending','in_progress','resolved','closed'],true)){$s=db()->prepare('UPDATE queries SET status=?,admin_response=? WHERE id=?');$s->execute([$status,$response?:null,$id]);flash('Query updated.');}go('index.php');}$stats=db()->query("SELECT COUNT(*) total,SUM(status='pending') pending,SUM(status='resolved') resolved FROM queries")->fetch();$qs=db()->query('SELECT q.*,u.name student_name,u.email student_email,u.student_id FROM queries q JOIN users u ON u.id=q.user_id ORDER BY q.created_at DESC')->fetchAll();$pageTitle='Admin dashboard';require '../includes/header.php';?><span class="eyebrow">ADMINISTRATION</span><h1>Query management</h1><p>Review student questions and update status or response.</p><div class="stats"><div class="stat">Total<strong><?= (int)$stats['total']?></strong></div><div class="stat">Pending<strong><?= (int)$stats['pending']?></strong></div><div class="stat">Resolved<strong><?= (int)$stats['resolved']?></strong></div></div><?php if(!$qs):?><div class="empty">No student queries yet.</div><?php endif;?><?php foreach($qs as $q):?><div class="panel"><h2>#<?= (int)$q['id']?> — <?=e($q['subject'])?></h2><p><b>Student:</b> <?=e($q['student_name'])?> · <?=e($q['student_email'])?> <?= $q['student_id']?'· ID: '.e($q['student_id']):''?></p><p><b>Category:</b> <?=e($q['category'])?></p><p><?=nl2br(e($q['message']))?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$q['id']?>"><div class="field"><label>Admin response</label><textarea name="response" maxlength="5000"><?=e($q['admin_response']??'')?></textarea></div><div class="field"><label>Status</label><select name="status"><?php foreach(['pending'=>'Pending','in_progress'=>'In progress','resolved'=>'Resolved','closed'=>'Closed'] as $v=>$label):?><option value="<?=e($v)?>" <?=$q['status']===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><button class="btn primary">Save update</button></form><p class="muted">Submitted: <?=e($q['created_at'])?></p></div><?php endforeach;?><?php require '../includes/footer.php';?>